/// <summary>
/// PricingAttribute of table <c>SalesTable</c> field CashDiscPercent.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesTable, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeSalesTableCashDiscPercent extends UPSPricingAttributeSalesTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(SalesTable, CashDiscPercent);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Real);
    SalesTable salesTable;
    while select CashDiscBaseDays from salesTable
        group by CashDiscBaseDays
    {
        ret.add(salesTable.CashDiscPercent);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(SalesTable, CashDiscPercent));
    qbr.value(queryValue(_value));
}
